<template>
<v-card rounded="xl" flat border class="mb-4"><v-card-title>无人机实时连接</v-card-title><v-card-text><v-alert v-if="error" type="error" class="mb-3">{{error}}</v-alert><v-expansion-panels variant="accordion" class="mb-4"><v-expansion-panel title="遥控器第一次连接：查看接入地址"><v-expansion-panel-text><p>电脑与遥控器连接同一局域网。DJI 的 RTMP 地址填下面的地址，推流码填 drone（多台设备使用不同推流码）。</p><v-text-field v-model="host" label="接收电脑局域网 IP"/><v-text-field :model-value="host?'rtmp://'+host+':1935/live/':''" label="RTMP 地址" readonly/><v-text-field model-value="drone" label="推流码示例" readonly/></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
<v-list><v-list-item v-for="s in sessions.filter(s=>!['REJECTED','DISCONNECTED'].includes(s.state))" :key="s.id" :title="s.stream_path" :subtitle="labels[s.state]+' · '+dateText(s.created_at)" :active="current?.id===s.id" @click="open(s)"><template #append><template v-if="s.state==='PENDING'"><v-btn color="primary" @click.stop="confirm(s)">确认接入</v-btn><v-btn color="grey-darken-1" variant="outlined" @click.stop="action(s,'reject')">忽略</v-btn></template></template></v-list-item></v-list><div v-if="!sessions.length" class="empty">正在等待遥控器推流…</div>
<div v-if="current && !['PENDING','REJECTED'].includes(current.state)"><v-chip class="mb-3">本次连接：{{current.id.slice(0,8)}} · {{labels[current.state]}}</v-chip><iframe v-if="current.state!=='DISCONNECTED'" :src="preview" title="无人机实时视频" class="live-video" allow="autoplay; fullscreen"/><v-alert v-else type="warning">连接已断开，本次识别和预测记录已保留。重新推流会生成新的待确认连接。</v-alert><div class="two mt-4"><v-select v-model="mode" :items="[{title:'手动截取',value:'MANUAL'},{title:'自动截取（每秒一次）',value:'AUTO'}]" label="截取模式" :disabled="current.state==='RUNNING'" variant="outlined"/><div><v-btn v-if="['CONFIRMED','STOPPED'].includes(current.state)" color="primary" @click="$emit('start',{id:current.id,mode,monitoring_id:current.monitoring_id})">开始监控</v-btn><v-btn v-if="current.state==='RUNNING'" color="grey-darken-1" variant="outlined" @click="action(current,'stop')">停止</v-btn><v-btn v-if="current.state==='RUNNING'&&current.mode==='MANUAL'" class="ml-2" color="primary" @click="action(current,'capture')">截取并识别</v-btn></div></div><v-alert v-if="current.last_error" type="warning">{{current.last_error}}</v-alert><v-alert v-if="current.latest_sample" type="info" variant="tonal">最近截取：{{dateText(current.latest_sample.captured_at)}} · 检出 {{current.latest_sample.detection.detection.num_detections}} 个目标</v-alert><div v-if="current.latest_sample" class="actions-right"><v-btn color="primary" :loading="predicting" @click="predictSample">预测当前一帧</v-btn></div><v-alert v-if="manualPrediction" type="info" variant="tonal" class="mt-3">{{manualPrediction.result.conclusion||manualPrediction.result.reason}}</v-alert></div>
</v-card-text></v-card>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {dateText} from '../utils/display'
const emit=defineEmits(['select','start','sample','running','prediction']);const props=defineProps({activeMonitoringId:String})
const manualPrediction=ref(null),predicting=ref(false)
const sessions=ref([]),current=ref(null),mode=ref('MANUAL'),host=ref(''),error=ref('');let timer,busy=false,lastSample=''
const labels={PENDING:'待确认',CONFIRMED:'已确认，待开始',RUNNING:'监控中',STOPPED:'已停止',DISCONNECTED:'已断开',REJECTED:'已忽略'}
const preview=computed(()=>current.value?'http://'+location.hostname+':8888/'+current.value.stream_path+'?autoplay=true&muted=true&playsInline=true':'')
async function api(url,body){const r=await fetch('/api'+url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.detail||j.message||'接收服务请求失败，请检查后台服务');return j}
async function poll(){if(busy)return;busy=true;try{const r=await api('/live/sessions');sessions.value=r.sessions;error.value=r.receiver_error||'';if(current.value){const entry=sessions.value.find(s=>s.id===current.value.id);if(!entry){current.value=null;manualPrediction.value=null;emit('running',false);return}current.value=await api('/live/sessions/'+entry.id);emit('running',current.value.state==='RUNNING');const sample=current.value.latest_sample;if(sample&&sample.detection.id!==lastSample){lastSample=sample.detection.id;emit('sample',sample)}}}catch(e){error.value=e.message}finally{busy=false}}
async function open(s){manualPrediction.value=null;current.value=s;mode.value=s.mode;if(s.state!=='PENDING'&&s.state!=='REJECTED')emit('select',await api('/records/'+s.monitoring_id))}
async function predictSample(){if(!current.value?.latest_sample)return;predicting.value=true;error.value='';try{manualPrediction.value=await api('/records/'+current.value.monitoring_id+'/repredict',{detection_id:current.value.latest_sample.detection.id});emit('prediction',manualPrediction.value)}catch(e){error.value=e.message}finally{predicting.value=false}}
async function action(s,action){try{await api('/live/sessions/'+s.id+'/'+action,{});await poll()}catch(e){error.value=e.message}}
async function confirm(s){try{const updated=await api('/live/sessions/'+s.id+'/confirm',{});await open(updated);await poll()}catch(e){error.value=e.message}}
onMounted(async()=>{await poll();try{const n=await api('/live/receiver');host.value=n.addresses[0]||''}catch(e){error.value=e.message}timer=setInterval(poll,2000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<style scoped>.live-video{display:block;width:100%;height:380px;border:0;border-radius:12px;background:#111}</style>
